/*
 * デザインシステムの基礎 — 見た目の値の唯一の置き場
 * （specs/038-design-system/research.md R-5、ui-design.md「Foundations」）。
 *
 * 色は shadcn の意味名と vv 固有の役割で、6 桁の hex（overlay だけ半透明）。暗い配色の
 * 1 組だけを持つ。画面はここから生成される実用クラス（bg-card、text-muted-foreground、
 * rounded-md、gap-3 など）だけを使う。使い方の規則は web/registry/rules/foundations.md、
 * 生の色と対比の検査は src/theme/tokens.test.ts。
 */
@theme {
  /*
   * --- 段階を持つ名前空間を Tailwind の既定から空にする（research.md R-8）。ここで定めた
   * 段だけが実用クラスになり、段階の外（p-7、text-2xl、rounded-xl、font-bold、bg-red-500
   * など）は生成されず、web/eslint.config.js の no-unknown-classes で落ちる。
   * tw-animate-css の animate-in などもここで消えるので、動きは下の段だけを使う。 ---
   */
  --color-*: initial;
  --text-*: initial;
  --font-weight-*: initial;
  --spacing: initial;
  --spacing-*: initial;
  --radius-*: initial;
  --shadow-*: initial;
  --drop-shadow-*: initial;
  --animate-*: initial;

  /* --- 面（暗い順に navbar・background・muted・card・popover）と文字 --- */
  --color-navbar: #000000;
  --color-background: #111111;
  --color-foreground: #f2f2f2;
  --color-muted: #191919;
  --color-muted-foreground: #b3b3b3;
  --color-card: #212121;
  --color-card-foreground: #f2f2f2;
  --color-popover: #2b2b2b;
  --color-popover-foreground: #f2f2f2;

  /* --- 副次の操作・チップ、hover と強調した行（shadcn の accent。ブランド色ではない） --- */
  --color-secondary: #363636;
  --color-secondary-foreground: #f2f2f2;
  --color-accent: #363636;
  --color-accent-foreground: #f2f2f2;

  /* --- VVMDM のシアン: 1 区画に 1 つの主操作・選択・進行。押下と選択には濃い版を使う。 --- */
  --color-primary: #3ec1d3;
  --color-primary-hover: #68cedc;
  --color-primary-active: #29a4b5;
  --color-primary-foreground: #111111;
  --color-primary-soft: #163b40;

  /* --- 線とフォーカス --- */
  --color-border: #383838;
  --color-input: #7a7a7a;
  --color-ring: #68cedc;

  /* --- 状態。いつも文言と印を添える。 --- */
  --color-destructive: #ff8a80;
  --color-destructive-strong: #b8363c;
  --color-destructive-foreground: #ffffff;
  --color-destructive-soft: #4b2023;
  --color-warning: #f5b452;
  --color-warning-foreground: #111111;
  --color-warning-soft: #4c3520;
  --color-success: #5fd39a;
  --color-success-foreground: #111111;
  --color-success-soft: #204334;

  /* --- お気に入りの印だけの色（specs/035-favorites/ui-design.md「Mark」） --- */
  --color-favorite: #ff6f9c;

  /* --- ダイアログの後ろとサムネイルの上（ただ一つの半透明） --- */
  --color-overlay: rgb(0 0 0 / 0.88);

  /* --- 書体と文字の 6 段階。太さは normal・medium・semibold の 3 種。 --- */
  --font-sans:
    "Inter Variable", "Noto Sans JP Variable", system-ui, -apple-system, "Segoe UI",
    "Hiragino Sans", sans-serif;
  --text-2xs: 0.6875rem;
  --text-2xs--line-height: 1rem;
  --text-xs: 0.75rem;
  --text-xs--line-height: 1rem;
  --text-sm: 0.875rem;
  --text-sm--line-height: 1.25rem;
  --text-base: 1rem;
  --text-base--line-height: 1.5rem;
  --text-lg: 1.125rem;
  --text-lg--line-height: 1.75rem;
  --text-xl: 1.25rem;
  --text-xl--line-height: 1.75rem;
  /* 動画ページの題名の sm 以上の大きさ（player/VideoTitle.tsx） */
  --text-video-title: 1.5rem;
  --text-video-title--line-height: 1.375;
  --font-weight-normal: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  /*
   * --- 余白と大きさ: 4px 格子の 0・px・0.5・1・1.5・2・3・4・5・6・8・9・10・
   * 12・16 と、次の名前つきの段。ほかの数値の段は生成されない。 ---
   */
  --spacing-0: 0px;
  --spacing-0\.5: 0.125rem;
  --spacing-1: 0.25rem;
  --spacing-1\.5: 0.375rem;
  --spacing-2: 0.5rem;
  --spacing-3: 0.75rem;
  --spacing-4: 1rem;
  --spacing-5: 1.25rem;
  --spacing-6: 1.5rem;
  --spacing-8: 2rem;
  --spacing-9: 2.25rem;
  --spacing-10: 2.5rem;
  --spacing-12: 3rem;
  --spacing-16: 4rem;
  --spacing-navbar: 3.25rem;
  --spacing-sidebar: 14.5rem;
  --spacing-sidebar-rail: 4.25rem;
  /* レールの項目（アイコンの下に名前を出す正方形） */
  --spacing-rail-item: 3.5rem;
  --spacing-card-0: 13.75rem;
  --spacing-card-1: 17.5rem;
  --spacing-card-2: 22.5rem;
  --spacing-card-3: 30rem;
  /* 一覧表示の列（サムネイルの列・サムネイル・数値の列・広い数値の列） */
  --spacing-list-thumb-cell: 8rem;
  --spacing-list-thumb: 7rem;
  --spacing-list-number: 5rem;
  --spacing-list-number-wide: 6rem;
  --spacing-list-date: 7rem;
  /* ツールバーの検索欄の最小幅（狭い幅と sm 以上）とズームの幅 */
  --spacing-search-min: 5rem;
  --spacing-search-min-sm: 10rem;
  --spacing-zoom: 6rem;
  /* 選択バーの高さと、その下に隠れないよう一覧の末尾に足す余白 */
  --spacing-selection-bar: 2.75rem;
  --spacing-selection-bar-clearance: 6rem;
  /* ポップオーバーの幅とチップの名前の最大幅 */
  --spacing-popover: 18rem;
  --spacing-popover-wide: 20rem;
  --spacing-chip-label: 12rem;
  /* タグの名前を打つ Combobox（ui/Combobox.tsx）の入力の幅と候補の一覧の幅・最大の高さ、
     窓の中に置いた一覧の高さとその最大 */
  --spacing-combobox: 10rem;
  --spacing-combobox-list: 16rem;
  --spacing-combobox-panel: 15rem;
  --spacing-combobox-panel-max: 40vh;
  /* メニュー（DropdownMenu）の最小幅 */
  --spacing-menu: 11rem;
  /* 詳細ページの横の情報欄の幅（web/src/ui/patterns/detail-page.tsx）。xl からは広い方 */
  --spacing-detail-aside: 20rem;
  --spacing-detail-aside-wide: 24rem;
  /* 動画ページ: 関連動画の行のサムネイルの幅、前後の動画へのつまみの幅と最小の高さ（狭い幅と
     sm 以上）、状態の層の下に操作バーの分だけ空ける余白、バージョンの一覧の幅 */
  --spacing-related-thumb: 10rem;
  --spacing-neighbor-arrow: 1.75rem;
  --spacing-neighbor-arrow-min: 4.5rem;
  --spacing-neighbor-arrow-min-sm: 6rem;
  --spacing-control-bar-clearance: 3.5rem;
  --spacing-versions-popover: min(28rem, calc(100vw - 2rem));
  /* 動画ページ: 公開の切り替えの左右の余白と、技術情報の項目の左右の余白 */
  --spacing-visibility-x: 0.625rem;
  --spacing-technical-x: 0.625rem;
  /* 設定の取り込みの問題の一覧の最大の高さと、フォルダ選択の一覧の高さ */
  --spacing-issue-list: 50vh;
  --spacing-folder-list: 18rem;

  /* --- 角丸: sm（チェック・バッジ）、md（操作・カード・サムネイル）、lg（浮く層）、full --- */
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 10px;

  /* --- 影: 置いた面には付けず、hover のカードと浮く層と画像の上の印にだけ付ける --- */
  --shadow-card-hover: 0 0 0 1px rgb(255 255 255 / 0.1), 0 8px 24px rgb(0 0 0 / 0.45);
  --shadow-elevated: 0 0 0 1px rgb(255 255 255 / 0.06), 0 12px 32px rgb(0 0 0 / 0.55);
  --drop-shadow-mark: 0 1px 2px rgb(0 0 0 / 0.75);

  /*
   * --- 動き: fade-in・pop-in・slide-up と、読み込み中の shimmer・spin（Spinner）・pulse
   * （量の分からない Progress）。動きを減らす設定では止める。 ---
   */
  --ease-out-quart: cubic-bezier(0.25, 1, 0.5, 1);
  --animate-fade-in: fade-in 150ms var(--ease-out-quart);
  --animate-pop-in: pop-in 120ms var(--ease-out-quart);
  --animate-slide-up: slide-up 200ms var(--ease-out-quart);
  --animate-shimmer: shimmer 1.6s linear infinite;
  --animate-spin: spin 1s linear infinite;
  --animate-pulse: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;

  /* --- 再生画面のシークプレビュー（index.css の .vv-seek-preview。special の例外） --- */
  --size-seek-preview: clamp(160px, calc(89.41px + 19.61vw), 240px);
  --size-seek-preview-max: 240px;
  --spacing-seek-preview-gap: 18px;
  --spacing-seek-preview-unavailable-gap: 40px;
  --spacing-seek-preview-edge: 4px;
  --spacing-seek-preview-time-y: 2px;
  --spacing-seek-preview-time-x: 6px;
  --text-seek-preview: 11px;
  --duration-seek-preview: 100ms;

  @keyframes fade-in {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }
  @keyframes pop-in {
    from {
      opacity: 0;
      transform: scale(0.97);
    }
    to {
      opacity: 1;
      transform: scale(1);
    }
  }
  @keyframes slide-up {
    from {
      opacity: 0;
      transform: translateY(8px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
  @keyframes spin {
    to {
      transform: rotate(360deg);
    }
  }
  @keyframes pulse {
    50% {
      opacity: 0.5;
    }
  }
  @keyframes shimmer {
    from {
      background-position: -200% 0;
    }
    to {
      background-position: 200% 0;
    }
  }
}

/*
 * 動画ページのプレイヤーの枠（player/VideoPage.tsx）。高さの上限は、見出しの帯と題名・タグ・
 * 情報の行が画面に収まる高さ（狭い幅は 12.25rem、lg からは 17rem を引き、15rem を下回らない）。
 * 幅の上限はその高さに動画の比率（16:9 より細いときは 16:9）を掛けた値で、比率は実行時に枠が
 * `--vv-video-aspect` として持つ。値が要素の変数を読むので、:root の変数にせず実用クラスへ
 * 直に書き込む（inline）。
 */
@theme inline {
  --spacing-player-height: calc(100dvh - 12.25rem);
  --spacing-player-height-lg: max(100dvh - 17rem, 15rem);
  --spacing-player-width: calc((100dvh - 12.25rem) * max(var(--vv-video-aspect), 16 / 9));
  --spacing-player-width-lg: calc(
    max(100dvh - 17rem, 15rem) * max(var(--vv-video-aspect), 16 / 9)
  );
  --aspect-player: var(--vv-video-aspect);
}

/*
 * 読み込み中の面（Skeleton）の光の帯。animate-shimmer が背景の位置を動かす。
 */
@utility bg-shimmer {
  background-image: linear-gradient(
    90deg,
    transparent 0%,
    var(--color-secondary) 50%,
    transparent 100%
  );
  background-size: 200% 100%;
}
